script:
frappe.ui.form.on('Stock Entry', {

    onload(frm){
	    set_carton_filters(frm)
	    toggle_items_read_only(frm);
    },
    
    refresh(frm){
	    set_carton_filters(frm)
	    toggle_items_read_only(frm);
    },
    
    from_warehouse(frm){
        set_carton_filters(frm);
        frm.clear_table("custom_carton_table");
        frm.refresh_field("custom_carton_table");
        
        if (frm.doc.custom_transfer_by_carton) {
            frm.clear_table("items");
            frm.refresh_field("items");
        }
    },

	company(frm){
	    set_carton_filters(frm)
	    frm.clear_table("custom_carton_table");
	    frm.refresh_field("custom_carton_table");
	    frm.clear_table("items");
        frm.refresh_field("items");
	},
	
custom_transfer_by_carton(frm) {
        frm.clear_table("items");
        frm.refresh_field("items");
        frm.clear_table("custom_carton_table");
        frm.refresh_field("custom_carton_table");

        toggle_items_read_only(frm);
        
        update_items_from_ctns(frm);
    }
});


frappe.ui.form.on('Stock Entry Carton', {
	
	custom_carton_table_remove(frm) {
        if (!frm.doc.custom_carton_table || frm.doc.custom_carton_table.length === 0) {
            frm.clear_table("items");
            frm.refresh_field("items");
        } else {
            update_items_from_ctns(frm);
        }
	},

	carton(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        
        if (row.carton) {
            let count = 0;
            
            frm.doc.custom_carton_table.forEach(d => {
                if (d.carton === row.carton) {
                    count++;
                }
            });
            
            if (count > 1) {
                frappe.msgprint(__("Le carton {0} a déjà été ajouté au tableau.", [row.carton]));
                frappe.model.set_value(cdt, cdn, "carton", ""); // Efface immédiatement la cellule
                return;
            }
        }
        
		update_items_from_ctns(frm);
	}
});



function update_items_from_ctns(frm) {
    
    
    const is_receipt = frm.doc.stock_entry_type === "Material Receipt";
    
    if(frm.doc.custom_carton_table.length == 0){
        frm.clear_table("items");
	    frm.refresh_field("items");
    }
    
	if (!frm.doc.custom_transfer_by_carton || !frm.doc.custom_carton_table.length) return;

	frm.clear_table("items");
	frm.refresh_field("items");

    const ctn_names = frm.doc.custom_carton_table.map(row => row.carton)


    console.log("the =>>>> " , ctn_names)
    
    frappe.call({
        method : "ctn_tracking_app.api.get_items_from_ctns",
        args : { ctn_list : ctn_names},
        freeze : true,
        freeze_message : "Fetching items from CTNs ...",
        callback : function(r){
            if(!r.message) return;
            frm.clear_table("items");
            r.message.forEach(item => {
                frm.add_child("items" , {
                    item_code         : item.item_code,
                    qty               : item.qty ,
                    uom               : item.uom || "",
                    stock_uom         : item.uom || "",
                    transfer_qty      : item.qty * item.conversion_factor,
                    conversion_factor : item.conversion_factor || 1 ,
                    s_warehouse       : is_receipt ? "" :item.s_warehouse,
                    t_warehouse       : frm.doc.to_warehouse //default to warhouse on issue just dont set it.
                })
            })
            
            frm.refresh_field("items");
            frappe.show_alert("Items updated from CTNs")
        }
    })

}



// Reusable filter function
function set_carton_filters(frm) {
    console.log("we are here : " , frm.doc.company)
    // 1. Filter for the main Warehouse field (as you already had)
    frm.set_query("from_warehouse", function() {
        return {
            filters: { "company": frm.doc.company }
        };
    });

    // 2. Filter the 'carton' field INSIDE the Child Table 'custom_carton_table'
    frm.set_query("carton", "custom_carton_table", function(doc, cdt, cdn) {
        let filtres = {
            "company": frm.doc.company
        };

        if (frm.doc.from_warehouse) {
            filtres["warehouse"] = frm.doc.from_warehouse; 
        } else {
            
            filtres["warehouse"] = "Sélectionnez un entrepôt d'abord";
        }

        return {
            filters: filtres
        };
    });
}
function toggle_items_read_only(frm) {
    if (frm.doc.custom_transfer_by_carton) {
        frm.set_df_property("items", "read_only", 1);
    } else {
        frm.set_df_property("items", "read_only", 0);
    }
}

frappe.ui.form.on("Carton", {
  refresh(frm) {

    // If the document is already saved (not new):
    if (!frm.is_new()) {
      frm.set_df_property("ref"       , "read_only", 1);
      frm.set_df_property("ctn_num"   , "read_only", 1);
      frm.set_df_property("items"     , "read_only", 1);
      frm.set_df_property("company"   , "read_only", 1);
      frm.set_df_property("warehouse" , "read_only", 1);
    } else {
      frm.set_df_property("ref", "read_only", 0);
    }

    // Fetch transactions if saved
    if (!frm.is_new()) {
        frappe.call({
            method: "ctn_tracking_app.ctn_tracking_app.doctype.carton.carton.get_transactions",
            args: {
                carton_name: frm.doc.name
            },
            callback: function(r) {
                if (r.message) {
                    let data = r.message;
                    console.log("data ==> ", data)

                    // Build a Bootstrap-styled table with border-radius, no top margin
                    let html = `
                        <div class="table-responsive"
                            style="border: 1px solid #dee2e6; 
                            border-radius: 6px; 
                            overflow: hidden; 
                            margin: 0; 
                            padding: 0;">
                        <table class="table table-hover table-striped mb-0" style="margin: 0;">
                            <thead>
                                <tr>
                                    <th>Type</th>
                                    <th>Reference</th>
                                    <th>Item</th>
                                    <th>Qty</th>
                                </tr>
                            </thead>
                        <tbody>
                    `;

                    data.forEach(row => {
                        console.log("row ==--==> " , row)
                        html += `
                            <tr>
                                <td>${row.type || ""}</td>
                                <td>${row.ref || ""}</td>
                                <td>${row.item || ""}</td>
                                <td>${row.qty}</td>
                            </tr>
                        `;
                    });

                    html += `
                        </tbody>
                        </table>
                        </div>
                    `;


                    // Inject into the HTML field
                    frm.fields_dict["transactions_html"].$wrapper.html(html);


                    // 2) Now compute the "current state" of each Item.
                    //    doc.items holds the initial quantities,
                    //    and that each transaction row is an "outbound" (subtract) quantity.

                    let itemMap = {};

                    // A) Start with the "init items" in the CTN

                    if (frm.doc.items) {
                        frm.doc.items.forEach(initRow => {
                            console.log("initRow ==> " , initRow)
                            if (initRow.item) {
                                itemMap[initRow.item] = (itemMap[initRow.item] || 0) + (initRow.qty || 0);
                            }
                        });
                    }


                            console.log("itemMap ==> " , itemMap)

                    // B) Add the transaction quantities
                    data.forEach(txn => {
                        if (txn.item) {
                            if(txn.type == "In"){
                                itemMap[txn.item] = (itemMap[txn.item] || 0) + (txn.qty || 0);
                            }else {
                                itemMap[txn.item] = (itemMap[txn.item] || 0) - (txn.qty || 0);    
                            }

                        }
                    });


                    // 3) Build a second table for the "CTN Status" HTML field
                    let statusHtml = `
                        <div class="table-responsive"
                            style="border: 1px solid #dee2e6;
                            border-radius: 6px;
                            overflow: hidden;
                            margin-top: 1rem;">
                            <table class="table table-hover table-striped mb-0" style="margin: 0;">
                                <thead>
                                    <tr>
                                        <th>Item</th>
                                        <th>Remaining Qty</th>
                                    </tr>
                                </thead>
                            <tbody>
                    `;


                    Object.keys(itemMap).forEach(itemCode => {
                        statusHtml += `
                            <tr>
                                <td>${itemCode}</td>
                                <td>${itemMap[itemCode]}</td>
                            </tr>
                        `;
                    });


                    statusHtml += `
                        </tbody>
                        </table>
                        </div>
                    `;

                    // 4) Inject the status table into your "ctn_status_html" field
                    frm.fields_dict["ctn_status_html"].$wrapper.html(statusHtml);

                }else{

                    // If no transactions found, clear the fields (or show a message)
                    frm.fields_dict["transactions_html"].$wrapper.html("");
                    frm.fields_dict["ctn_status_html"].$wrapper.html("No Transactions Found.");
                }
            }
        });
    } else {
      // If it's a new doc, clear both HTML fields
      frm.fields_dict["transactions_html"].$wrapper.html("");
      frm.fields_dict["ctn_status_html"].$wrapper.html("");
    }
  },

  company(frm){
      frm.set_query("warehouse", function() {
            return { filters: { company: frm.doc.company } };
        });
  }
});

frappe.ui.form.on("Stock Entry", {
	onload(frm) {
		setup_incident_reason_query(frm);
	},

	refresh(frm) {
		setup_incident_reason_query(frm);
		toggle_incident_fields(frm);
	},

	purpose(frm) {
		reset_incident_if_needed(frm);
		setup_incident_reason_query(frm);
		toggle_incident_fields(frm);
	},

	stock_entry_type(frm) {
		reset_incident_if_needed(frm);
		setup_incident_reason_query(frm);
		toggle_incident_fields(frm);
	},

	custom_is_stock_incident(frm) {
		if (!frm.doc.custom_is_stock_incident) {
			frm.set_value("custom_incident_reason", "");
			frm.set_value("custom_reported_by", "");
			frm.set_value("custom_incident_notes", "");
		} else {
			autofill_reported_by(frm);
		}
		toggle_incident_fields(frm);
	},
});

function is_issue_or_receipt(frm) {
	const purpose = frm.doc.purpose || "";
	const entry_type = frm.doc.stock_entry_type || "";
	return (
		["Material Issue", "Material Receipt"].includes(purpose) ||
		["Material Issue", "Material Receipt"].includes(entry_type)
	);
}

function incident_applies_to(frm) {
	const purpose = frm.doc.purpose || frm.doc.stock_entry_type || "";
	if (purpose === "Material Receipt") {
		return "Receipt";
	}
	return "Issue";
}

function toggle_incident_fields(frm) {
	const show = is_issue_or_receipt(frm);
	frm.toggle_display("custom_incident_section", show);
	frm.toggle_display("custom_is_stock_incident", show);

	const show_details = show && Number(frm.doc.custom_is_stock_incident);
	[
		"custom_cb_incident",
		"custom_incident_reason",
		"custom_incident_details_sb",
		"custom_reported_by",
		"custom_cb_incident_details",
		"custom_incident_notes",
	].forEach((field) => frm.toggle_display(field, show_details));

	frm.toggle_reqd("custom_incident_reason", show_details);
}

function reset_incident_if_needed(frm) {
	if (is_issue_or_receipt(frm)) {
		return;
	}
	if (frm.doc.custom_is_stock_incident) {
		frm.set_value("custom_is_stock_incident", 0);
	}
	frm.set_value("custom_incident_reason", "");
	frm.set_value("custom_reported_by", "");
	frm.set_value("custom_incident_notes", "");
}

function setup_incident_reason_query(frm) {
	if (!frm.fields_dict.custom_incident_reason) {
		return;
	}
	frm.set_query("custom_incident_reason", function () {
		return {
			filters: {
				is_active: 1,
				applies_to: ["in", [incident_applies_to(frm), "Both"]],
			},
		};
	});
}

function autofill_reported_by(frm) {
	if (frm.doc.custom_reported_by || !frm.fields_dict.custom_reported_by) {
		return;
	}
	frappe.db.get_value("Employee", { user_id: frappe.session.user }, "name").then((r) => {
		if (r && r.message && r.message.name && !frm.doc.custom_reported_by) {
			frm.set_value("custom_reported_by", r.message.name);
		}
	});
}
